#### 分段函数计算
```c
#include<stdio.h>
#include<math.h>
int main()
{
    double x;
    scanf("%lf",&x);
    if(x<1&&x>0)
        printf("%.2f",x);
    else if(x<1&&x<0)
        printf("%.2f",-x);
    else if(x>=1&&x<10)
        printf("%.2f",pow(x,3.6));
