#### 三个整数排序
```c
#include<stdio.h>
int main()
{
    int a,b,c,n,m;
    scanf("%d%d%d",&a,&b,&c);
    if(a>b&&a>c)
        n=a;
    else if(b>a&&b>c)
        n=b;
    else if(c>a&&c>b)
        n=c;
    if(a<b&&a<c)
        m=a;
    else if(b<a&&b<c)
        m=b;
    else if(c<a&&c<b)
        m=c;
    printf("%d,%d,%d",m,a+b+c-m-n,n);
    return 0;
}
```

