####  极坐标求两点距离
```c
#include<stdio.h>
#include<math.h>
#define pi 3.141592653589793
int main(){
    double a1,b1,a2,b2,l;
    scanf("%lf%lf\n%lf%lf",&a1,&b1,&a2,&b2);
    b1=b1*pi/180;
    b2=b2*pi/180;
    l=pow(a1*a1+a2*a2-2*a1*a2*cos(b1-b2),0.5);
    printf("distance=%.2lf",l);
}
```

